-- Base inicial gerada da planilha de referência.

do $$ declare c integer; v numeric(14,4); begin
  select count(*),sum(case when com_vinculo then t.valor_com_vinculo else t.valor_integral end) into c,v
  from public.gratificacoes g join public.tipos_gratificacao t on t.id=g.tipo_id where g.ativo;
  if c <> 78 or v <> 821607.0825 then raise exception 'Falha de regressão: % registros, % pagos',c,v; end if;
end $$;
